# Try to use xctest to run a simple test that finds Display & Brightness
# Or let's try a different approach - let's run a command to directly access Display settings

# Try to create and run a simple test script using xcodebuild
cat > /tmp/SettingsUITest/SettingsNavigationTest.swift << 'EOF'
import XCTest

class SettingsNavigationTest: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testOpenDisplaySettings() {
        let settingsApp = XCUIApplication(bundleIdentifier: "com.apple.Preferences")
        settingsApp.launch()

        // Wait for the app to load
        sleep(2)

        // Try to find Display & Brightness by searching
        let searchField = settingsApp.searchFields.firstMatch
        if searchField.exists {
            searchField.tap()
            searchField.typeText("Display")
        }
    }
}
EOF

